document.addEventListener('DOMContentLoaded',()=>{const c=window.APEX_CONFIG||{},d=document.querySelector('#apex-contact-dialog');document.querySelectorAll('[data-apex-contact]').forEach(a=>{let url=c.whatsapp?'https://wa.me/'+c.whatsapp.replace(/\D/g,'')+'?text='+encodeURIComponent('Hi Apex Auto Detailing, I would like a quote.'):'';const label=(a.getAttribute('aria-label')||a.textContent).toLowerCase();if(label.includes('direction'))url=c.mapsUrl||'';if(label.includes('instagram'))url=c.instagramUrl||'';if(label.includes('facebook'))url=c.facebookUrl||'';if(a.classList.contains('fsd-link')&&c.phone){url='tel:'+c.phone;a.textContent=c.phone;}if(url){a.href=url}else{a.removeAttribute('target');a.addEventListener('click',e=>{e.preventDefault();d.showModal()})}});d.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>d.close()));document.querySelector('#apex-gallery-button')?.addEventListener('click',()=>document.querySelector('#gallery').scrollIntoView({behavior:'smooth'}));});
